if "GROQ_API_KEY" not in os.environ:
     os.environ["GROQ_API_KEY"] = getpass.getpass("Enter your Groq API key: ")

# Initialize Groq LLM for generation
model = init_chat_model("groq:meta-llama/llama-4-maverick-17b-128e-instruct",temperature=0.5,max_tokens=512,timeout=None)

retriever=vectordb.as_retriever()

# RAG prompt for answer generation
template = (
    "You are an assistant for question-answering tasks regarding NACCAS policies. "
    "Use the following pieces of retrieved context to answer the question. "
    "If you don't know the answer, just say that you don't know. "
    "Use 25 sentences maximum and keep the answer concise.\n"
    "Question: {question} \n"
    "Context: {context}"
)
prompt = ChatPromptTemplate.from_template(template)

def format_docs(docs):
    return "\n\n".join(doc.page_content for doc in docs)

rag_chain = prompt | model | StrOutputParser()

# Question re-writer
re_write_prompt = PromptTemplate(
    template="""You are a question re-writer that converts an input question to a better version optimized for vectorstore retrieval.
    Look at the initial and formulate an improved question.
    Here is the initial question: \n\n {question}. Improved question with no preamble: \n """,
    input_variables=["question"],
)
question_rewriter = re_write_prompt | model | StrOutputParser()

# Define graph state
class GraphState(TypedDict):
    question: str
    generation: str
    documents: List[str]

# Graph nodes
def retrieve(state):
    print("---RETRIEVE---")
    question = state["question"]
    documents = retriever.get_relevant_documents(question)
    return {"documents": documents, "question": question}

def generate(state):
    print("---GENERATE---")
    question = state["question"]
    documents = state["documents"]
    generation = rag_chain.invoke({"context": format_docs(documents), "question": question})
    return {"documents": documents, "question": question, "generation": generation}

def grade_documents(state, similarity_threshold=0.5):
    print("---CHECK DOCUMENT RELEVANCE TO QUESTION (COSINE SIMILARITY)---")
    question = state["question"]
    documents = state["documents"]
    query_embedding = embedding_model.embed_query(question)
    filtered_docs = []
    for d in documents:
        doc_embedding = embedding_model.embed_query(d.page_content)
        similarity = cosine_similarity([query_embedding], [doc_embedding])[0][0]
        print(f"---DOCUMENT SIMILARITY SCORE: {similarity:.4f}---")
        if similarity >= similarity_threshold:
            print("---GRADE: DOCUMENT RELEVANT---")
            filtered_docs.append(d)
        else:
            print("---GRADE: DOCUMENT NOT RELEVANT---")
    return {"documents": filtered_docs, "question": question}

def transform_query(state):
    print("---TRANSFORM QUERY---")
    question = state["question"]
    documents = state["documents"]
    better_question = question_rewriter.invoke({"question": question})
    return {"documents": documents, "question": better_question}

# Graph edges
def decide_to_generate(state):
    print("---ASSESS GRADED DOCUMENTS---")
    filtered_documents = state["documents"]
    if not filtered_documents:
        print("---DECISION: ALL DOCUMENTS ARE NOT RELEVANT, TRANSFORM QUERY---")
        return "transform_query"
    else:
        print("---DECISION: GENERATE---")
        return "generate"

def grade_generation_v_documents_and_question(state, similarity_threshold=0.5):
    print("---CHECK HALLUCINATIONS (COSINE SIMILARITY)---")
    question = state["question"]
    documents = state["documents"]
    generation = state["generation"]

    # Hallucination check: compare generation embedding to document embeddings
    generation_embedding = embedding_model.embed_query(generation)
    doc_embeddings = [embedding_model.embed_query(doc.page_content) for doc in documents]
    similarities = [cosine_similarity([generation_embedding], [doc_emb])[0][0] for doc_emb in doc_embeddings]
    max_similarity = max(similarities) if similarities else 0.0
    print(f"---HALLUCINATION SIMILARITY SCORE: {max_similarity:.4f}---")

    if max_similarity >= similarity_threshold:
        print("---DECISION: GENERATION IS GROUNDED IN DOCUMENTS---")
        # Answer relevance check: compare generation embedding to query embedding
        print("---GRADE GENERATION vs QUESTION (COSINE SIMILARITY)---")
        query_embedding = embedding_model.embed_query(question)
        answer_similarity = cosine_similarity([generation_embedding], [query_embedding])[0][0]
        print(f"---ANSWER SIMILARITY SCORE: {answer_similarity:.4f}---")
        if answer_similarity >= similarity_threshold:
            print("---DECISION: GENERATION ADDRESSES QUESTION---")
            return "useful"
        else:
            print("---DECISION: GENERATION DOES NOT ADDRESS QUESTION---")
            return "not useful"
    else:
        print("---DECISION: GENERATION IS NOT GROUNDED IN DOCUMENTS, RE-TRY---")
        return "not supported"

# Build graph
workflow = StateGraph(GraphState)
workflow.add_node("retrieve", retrieve)
workflow.add_node("grade_documents", grade_documents)
workflow.add_node("generate", generate)
workflow.add_node("transform_query", transform_query)
workflow.add_edge(START, "retrieve")
workflow.add_edge("retrieve", "grade_documents")
workflow.add_conditional_edges(
    "grade_documents",
    decide_to_generate,
    {"transform_query": "transform_query", "generate": "generate"},
)
workflow.add_edge("transform_query", "retrieve")
workflow.add_conditional_edges(
    "generate",
    grade_generation_v_documents_and_question,
    {"not supported": "generate", "useful": END, "not useful": "transform_query"},
)

# Compile graph
app = workflow.compile()

# Evaluation function
def extract_qas(path):
    doc = Document(path)
    questions, truths = [], []
    q, t, mode = "", "", None
    for para in doc.paragraphs:
        text = para.text.strip()
        if not text:
            continue
        match = re.match(r'^(\d+)[\.\)]?\s*(.+)', text)
        if match:
            if q and t:
                questions.append(q.strip())
                truths.append(t.strip())
            q = match.group(2).strip()
            t, mode = "", None
        elif text.lower().startswith("ground truth"):
            mode = "truth"
        elif mode == "truth":
            t += " " + text.strip()
    if q and t:
        questions.append(q.strip())
        truths.append(t.strip())
    return questions, truths

# Run evaluation
docx_path = "/content/drive/MyDrive/model Generated Response and Scores(1).docx"
questions, ground_truths = extract_qas(docx_path)
print(f"Extracted {len(questions)} QAs.")

output_path = "/content/selfrag_qwen3_results.txt"
with open(output_path, "w", encoding="utf-8") as f:
    for i, (q, gt) in enumerate(zip(questions, ground_truths), 1):
        try:
            inputs = {"question": q}
            start = time.time()
            for output in app.stream(inputs, {"recursion_limit": 5}):
                for _, value in output.items():
                    pass
            response = value["generation"]
            end = time.time()
            P, R, F1 = score([response], [gt], lang="en")
            p, r, f1_score = P.item(), R.item(), F1.item()
            f.write(f"Q{i}: {q}\nResponse: {response}\nGround Truth: {gt}\n")
            f.write(f"BERTScore -> P: {p:.4f}, R: {r:.4f}, F1: {f1_score:.4f}\n")
            f.write(f"Time: {end - start:.2f} sec\n{'-'*80}\n")
            print(f"\nQ{i}: {q}")
            print(f"Response: {response}")
            print(f"Ground Truth: {gt}")
            print(f"BERTScore -> P: {p:.4f}, R: {r:.4f}, F1: {f1_score:.4f}")
            print(f"Time: {end - start:.2f} sec")
            print("-" * 80)
        except Exception as e:
            print(f"\nQ{i}: {q}\n[Error during processing: {e}]")
            print("---" * 80 + "\n")
            f.write(f"Q{i}: {q}\n[Error during processing: {e}]\n{'-'*80}\n")
            continue

files.download(output_path)

